using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Runtime.InteropServices;using System.Web.Script.Serialization;using interop.ICApiIronCAD;
namespace RockPro{public static class LatchInProcess{static IZDoc D(object x){return x is IZDoc?(IZDoc)x:(IZDoc)Marshal.GetObjectForIUnknown(new IntPtr(Convert.ToInt64(x)));}public static int Run(string folder){var j=new JavaScriptSerializer{MaxJsonLength=64000000};var r=new Dictionary<string,object>();try{var q=(Dictionary<string,object>)j.DeserializeObject(File.ReadAllText(Path.Combine(folder,"request.json")));if(System.Diagnostics.Process.GetCurrentProcess().Id!=Convert.ToInt32(q["expected_pid"]))throw new Exception("Host changed");dynamic l=Marshal.GetActiveObject("IronCAD.Application");var app=(IZBaseApp)l.ZIronCADApp;if(!app.ApiVersion.StartsWith("29."))throw new Exception("2027 required");var docs=((Array)app.GetAllOpenDocs()).Cast<object>().Select(D).ToArray();if(docs.Any(d=>d.Name!=(string)q["output"]&&d.Name!=(string)q["original"]))throw new Exception("Unexpected user document, no restart");if(!File.Exists((string)q["snapshot"]))throw new Exception("Missing user snapshot");var copy=docs.Single(d=>d.Name==(string)q["output"]);var s=(IZSceneDoc)copy;string status=s.ParameterMgr.GetParameterByName("RP_IloscOkuc_Status").TextParameterValue;if(!status.Contains("Brak miejsca"))throw new Exception("Expected capacity status");r["status"]=status;var parameters=Enumerable.Range(0,s.ParameterMgr.Count).Select(i=>s.ParameterMgr.GetParameter(i)).Select(p=>new{name=p.Name,expression=p.Expression,value=p.Type==eZParamType.Z_PARAMETER_TYPE_TEXT?0:p.Value,notes=p.Notes}).ToArray();r["parameters"]=parameters;foreach(var a in AppDomain.CurrentDomain.GetAssemblies()){var t=a.GetType("RockPro.CAD.MountCountController");if(t!=null)t.GetMethod("Stop").Invoke(null,null);}var c=(IZCamera)s.CameraMgr.ActiveCamera;c.Perspective=false;c.Direction=new double[]{.65,.85,-.5};c.Up=new double[]{0,0,1};s.AdjustCameraToFitShapeInRect(1500,1100);s.Redraw();s.ExportImage(Path.Combine(folder,"final.png"),eZImageFormat.Z_IMAGE_PNG,1500,1100,true);s.SaveAs((string)q["output"],eZLinksSaveOptions.Z_LINKS_COPY_ALL,false);string saved=Path.Combine(Path.GetDirectoryName((string)q["snapshot"]),"RockPro_Hisense85_R004_przed_testem_autostartu_20261030.ics");if(File.Exists(saved))throw new Exception("Snapshot exists");s.SaveAsCopy(saved,eZLinksSaveOptions.Z_LINKS_COPY_ALL,false);r["saved_snapshot"]=saved;foreach(var doc in docs)doc.Close2(true);var remaining=app.GetAllOpenDocs() as Array;r["remaining_docs"]=remaining==null?0:remaining.Length;if(Convert.ToInt32(r["remaining_docs"])!=0)throw new Exception("Document still open");r["passed"]=true;}catch(Exception e){r["passed"]=false;r["error"]=e.ToString();}File.WriteAllText(Path.Combine(folder,"result.json"),j.Serialize(r));return (bool)r["passed"]?0:1;}}}